use super::*;

/// The institution a filename names, if it names one unambiguously.
///
/// The id must be followed by a SEPARATOR or the end of the stem, so `chase-2026-07.csv` matches and
/// `chaser-holdings.csv` does not. A bare prefix match would claim the second for Chase and then read
/// it with Chase's column layout.
pub fn institution_from_name(name: &str) -> Option<&'static str> {
    let stem = name.rsplit_once('.').map(|(s, _)| s).unwrap_or(name).to_ascii_lowercase();
    KNOWN.iter().copied().find(|id| {
        stem.strip_prefix(id)
            .is_some_and(|rest| rest.is_empty() || rest.starts_with(['-', '_', ' ', '.']))
    })
}
